import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the resolved
     * path and ensuring it stays within {@code dir}. It also rejects names that
     * contain path separators or the sequence "..".
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may come from an untrusted source)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null,
     *                                  empty, or contains invalid characters
     * @throws SecurityException        if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject obvious path traversal attempts
        if (name.contains("..") || name.contains("/") || name.contains("\\")) {
            throw new SecurityException("Invalid file name: " + name);
        }

        try {
            Path dirPath = dir.toPath().toAbsolutePath().normalize();
            Path targetPath = dirPath.resolve(name).normalize();

            // Ensure the target is still inside the base directory
            if (!targetPath.startsWith(dirPath)) {
                throw new SecurityException(
                        "Attempted directory traversal: " + targetPath);
            }

            File file = targetPath.toFile();

            // Resolve name collisions by appending "-n"
            String dot = name.lastIndexOf('.');
            String prefix = dot < 0 ? name : name.substring(0, dot);
            String suffix = dot < 0 ? "" : name.substring(dot);
            int index = 2;
            while (file.exists()) {
                file = new File(dir, prefix + "-" + index++ + suffix);
            }

            // Create parent directories if necessary
            File parent = file.getParentFile();
            if (parent != null && !parent.exists()) {
