     * @return {@code true} if the token is non‑null, non‑empty, contains only
     *         allowed characters, and has no control characters
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }

        // Trim to avoid accidental leading/trailing whitespace
        String trimmed = str.trim();
        if (trimmed.isEmpty()) {
            return false;
        }

        // Reject any control characters (CR, LF, etc.)
        for (int i = 0; i < trimmed.length(); i++) {
            if (Character.isISOControl(trimmed.charAt(i))) {
                return false;
            }
        }

        // Ensure the token matches the RFC 7230 definition
        return TOKEN_PATTERN.matcher(trimmed).matches();
