     * "#<elementId>".
     *
     * @param signature the XML signature to examine
     * @param elementId the ID of the element that should be covered
     * @return true if the signature references the element, false otherwise
     */
    private boolean isSignatureCoveringElement(Signature signature, String elementId) {
        if (signature == null || elementId == null) {
            return false;
        }
        for (Reference ref : signature.getSignedInfo().getReferenceList()) {
            String uri = ref.getURI();
            if (uri != null && uri.equals("#" + elementId)) {
                return true;
            }
        }
        return false;
    }

