import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;

class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from the given {@link InputStream} into the supplied
     * output buffer using a simple RLE scheme. The method validates the
     * input stream to guard against malformed data that could otherwise
     * cause an infinite loop or buffer overflow.
     *
     * @param in  the source stream containing compressed data
     * @param out the destination buffer to receive decompressed bytes
     * @throws IOException if the stream ends unexpectedly or contains
     *                     invalid packet sizes
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading packet header");
            }

            // A packet size of 0 is invalid in the Rgbe format and would
            // otherwise cause an infinite loop. Treat it as a protocol error.
            if (n == 0) {
                throw new IOException("Invalid RLE packet size 0 encountered");
            }

            if (n > 128) { // repeat packet
                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeat value");
                }
                int count = n & 0x7F; // number of repetitions
                if (position + count > total) {
                    throw new IOException("Repeat packet exceeds output buffer size");
                }
                byte v = (byte) value;
                for (int i = 0; i < count; i++) {
                    out[position++] = v;
                }
            } else { // literal packet
                int count = n;
                if (position + count > total) {
                    throw new IOException("Literal packet exceeds output buffer size");
                }
                for (int i = 0; i < count; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal bytes");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

    // other methods

    @Override
    public void close() throws IOException {
        in.close();
    }
}
