public class XsltRenderer implements Renderer {

    /**
     * A single, securely configured {@link TransformerFactory} instance.
     * The factory is configured once at class load time to enforce
     * secure processing and to prohibit external resource access.
     */
    private static final TransformerFactory TRANSFORMER_FACTORY = createSecureFactory();

