    /**
     * Creates a {@link Transformer} from the supplied XSLT template.
     *
     * @param templateStream the XSLT template as an {@link InputStream}
     * @return a securely configured {@link Transformer}
     * @throws IOException if the template stream cannot be read
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        try {
            // The StreamSource will consume the stream; it is closed in the finally block.
            return TRANSFORMER_FACTORY.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the stream is always closed to avoid resource leaks.
            try {
                templateStream.close();
            } catch (IOException closeEx) {
                // Log the exception in a real application; swallow here to avoid masking original error.
            }
        }
    }

    // other methods

    /**
     * Configures a {@link TransformerFactory} for secure processing.
     *
     * @return a factory instance with security features enabled
     */
    private static TransformerFactory createSecureFactory() {
        TransformerFactory factory = TransformerFactory.newInstance();

        // Enable the standard secure processing feature.
        try {
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (IllegalArgumentException | UnsupportedOperationException e) {
            // If the feature is not supported, log and continue; the factory will still be used.
