private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – the data is cached in a
    // temporary ByteArrayInputStream.
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // populate lastStoredEntry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Defensive checks for malformed ZIP entries.
    if (csize < 0) {
        throw new IOException("Negative entry size for stored entry: " + current.entry.getName());
    }
    if (csize == 0) {
        // No data to read – signal EOF immediately.
        return -1;
    }

    // If we've already consumed the declared size, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Refill the internal buffer if necessary.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        final int l = in.read(buf.array());
        if (l <= 0) {          // Handles both EOF (-1) and unexpected 0‑length reads.
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine how many bytes to copy to the caller.
    int toRead = Math.min(buf.remaining(), length);
    long remaining = csize - current.bytesRead;
    if (remaining < toRead) {
        toRead = (int) remaining; // remaining is guaranteed to fit in int here.
    }

    if (toRead <= 0) {
        // Either the entry is fully consumed or the stream is malformed.
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
