/**
 * A custom codec that safely deserialises JSON arrays into Java arrays.
 *
 * <p>This implementation mitigates the Fastjson deserialization vulnerability
 * (CVE‑2017‑18307) by enforcing a strict whitelist of acceptable component
 * types. Any attempt to deserialize an array whose component type is not
 * explicitly permitted results in an {@link IllegalArgumentException}. This
 * prevents attackers from injecting malicious class names (e.g. via
 * {@code rmi://} URIs) that could trigger remote code execution.</p>
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /* Whitelist of safe component types                                    */
    /* --------------------------------------------------------------------- */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES;
    static {
        Set<Class<?>> tmp = new HashSet<>();
        tmp.add(String.class);
        tmp.add(Byte.class);
        tmp.add(Short.class);
        tmp.add(Integer.class);
        tmp.add(Long.class);
        tmp.add(Float.class);
        tmp.add(Double.class);
        tmp.add(Boolean.class);
        tmp.add(Character.class);
        tmp.add(java.math.BigDecimal.class);
        tmp.add(java.math.BigInteger.class);
        tmp.add(java.util.Date.class);
        tmp.add(java.time.LocalDate.class);
        tmp.add(java.time.LocalDateTime.class);
        tmp.add(java.time.OffsetDateTime.class);
        tmp.add(java.time.ZonedDateTime.class);
        // Add more domain‑specific types here if required
        SAFE_COMPONENT_TYPES = Collections.unmodifiableSet(tmp);
    }

    /**
     * Checks whether a component type is allowed by the whitelist.
     *
     * @param cls the component class to check
     * @return true if the class is in the whitelist, false otherwise
     */
    private boolean isSafeComponentType(Class<?> cls) {
        return SAFE_COMPONENT_TYPES.contains(cls);
    }

    /* --------------------------------------------------------------------- */
    /* Deserialization logic                                                 */
    /* --------------------------------------------------------------------- */
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {
        final JSONLexer lexer = parser.lexer;

        // Handle JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        // Handle JSON string literal → byte[]
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        Class<?> componentClass;
        Type componentType;

        // Resolve component type for array
        if (type instanceof GenericArrayType) {
            GenericArrayType gArray = (GenericArrayType) type;
            componentType = gArray.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    ParameterizedType pType = (ParameterizedType) contextType;
                    Type raw = pType.getRawType();
                    Type actual = null;

                    if (raw instanceof Class) {
                        TypeVariable<?>[] params = ((Class<?>) raw).getTypeParameters();
                        for (int i = 0; i < params.length; ++i) {
                            if (params[i].getName().equals(typeVar.getName())) {
                                actual = pType.getActualTypeArguments()[i];
                                break;
                            }
                        }
                    }

                    componentClass = actual instanceof Class ? (Class<?>) actual : Object.class;
                } else {
                    componentClass = TypeUtils.getClass(typeVar.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else if (type instanceof Class && ((Class<?>) type).isArray()) {
            Class<?> clazz = (Class<?>) type;
            componentClass = clazz.getComponentType();
            componentType = componentClass;
        } else {
            throw new IllegalArgumentException("Expected an array type but got: " + type);
        }

        // Enforce whitelist – reject unsafe component types
        if (!isSafeComponentType(componentClass)) {
            throw new IllegalArgumentException(
                "Deserialization of array component type '" + componentClass.getName()
                + "' is not permitted for security reasons.");
        }

        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        return (T) toObjectArray(parser, componentClass, array);
    }

    /* --------------------------------------------------------------------- */
    /* Helper method – convert JSONArray to typed array                     */
    /* --------------------------------------------------------------------- */
    @SuppressWarnings("unchecked")
    private <T> T toObjectArray(DefaultJSONParser parser, Class<?> componentType, JSONArray array) {
        // Fastjson already provides a safe conversion; we simply cast.
        // The caller ensures componentType is whitelisted.
        return (T) array.toArray((Object[]) java.lang.reflect.Array.newInstance(componentType, array.size()));
    }

