import javax.xml.XMLConstants;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import org.apache.camel.Exchange;
import org.apache.camel.Converter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // -----------------------------------------------------------------------
    // Utility method to safely set a feature on a SAXParserFactory or XMLReader
    // -----------------------------------------------------------------------
    private static void setFeature(Object target, String name, boolean value) {
        try {
            if (target instanceof SAXParserFactory) {
                ((SAXParserFactory) target).setFeature(name, value);
            } else if (target instanceof XMLReader) {
                ((XMLReader) target).setFeature(name, value);
            }
        } catch (Exception e) {
            LOG.warn("Failed to set feature {} to {} on {}: {}", name, value, target.getClass().getSimpleName(), e.toString());
        }
    }

    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        // Prepare the InputSource from the StreamSource
        InputSource inputSource = (source.getReader() != null)
                ? new InputSource(source.getReader())
                : new InputSource(source.getInputStream());
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Reuse a factory from the exchange if available
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            setFeature(sfactory, XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Disable DTDs and external entities
            setFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            setFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            setFeature(sfactory, "http://xml.org/sax/features/external-general-entities", false);
            setFeature(sfactory, "http://xml.org/sax/features/external-parameter-entities", false);

            // Basic parser configuration
            sfactory.setNamespaceAware(true);
            sfactory.setValidating(false);          // Do not validate against a DTD/schema
            sfactory.setXIncludeAware(false);       // Disable XInclude

            // Create the parser and reader
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Disallow DOCTYPE declarations
            setFeature(xmlReader, "http://apache.org/xml/features/disallow-doctype-decl", true);

        } catch (ParserConfigurationException | SAXException e) {
            LOG.warn("Failed to create a secure SAXParser/XMLReader: {}", e.toString());
            throw e;   // Propagate the exception – caller cannot proceed without a reader
        }

        return new SAXSource(xmlReader, inputSource);
    }

    // other methods
}
